mkdir -p e2e src/test .github/workflows

cat > vitest.config.mts <<'EOF'
import react from "@vitejs/plugin-react";
import tsconfigPaths from "vite-tsconfig-paths";
import { defineConfig } from "vitest/config";

export default defineConfig({
  plugins: [tsconfigPaths(), react()],
  test: {
    environment: "jsdom",
    setupFiles: ["./src/test/setup.ts"],
    include: ["src/**/*.test.{ts,tsx}"],
    css: true,
    coverage: {
      provider: "v8",
      include: ["src/**/*.{ts,tsx}"],
      exclude: ["src/test/**", "src/**/*.test.{ts,tsx}"],
    },
  },
});
EOF

cat > src/test/setup.ts <<'EOF'
import "@testing-library/jest-dom/vitest";
import { cleanup } from "@testing-library/react";
import { afterEach } from "vitest";

afterEach(() => {
  cleanup();
});
EOF

cat > src/app/page.test.tsx <<'EOF'
import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import Home from "./page";

describe("Home", () => {
  it("renders the main heading", () => {
    render(<Home />);
    expect(screen.getByRole("heading", { level: 1 })).toBeInTheDocument();
  });
});
EOF

cat > playwright.config.ts <<'EOF'
import { defineConfig, devices } from "@playwright/test";

const PORT = Number(process.env.PORT ?? 3000);
const baseURL = `http://localhost:${PORT}`;

export default defineConfig({
  testDir: "./e2e",
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  workers: process.env.CI ? 1 : undefined,
  reporter: process.env.CI ? "github" : "list",
  use: {
    baseURL,
    trace: "on-first-retry",
  },
  projects: [
    { name: "chromium", use: { ...devices["Desktop Chrome"] } },
    { name: "mobile", use: { ...devices["Pixel 7"] } },
  ],
  webServer: {
    command: `pnpm build && pnpm start --port ${PORT}`,
    url: baseURL,
    reuseExistingServer: !process.env.CI,
    timeout: 180_000,
  },
});
EOF

cat > e2e/home.spec.ts <<'EOF'
import { expect, test } from "@playwright/test";

test("home page loads", async ({ page }) => {
  await page.goto("/");
  await expect(page.getByRole("heading", { level: 1 })).toBeVisible();
});
EOF

cat > .prettierrc.json <<'EOF'
{
  "plugins": ["prettier-plugin-tailwindcss"]
}
EOF

cat > .prettierignore <<'EOF'
.next
out
build
coverage
playwright-report
test-results
pnpm-lock.yaml
next-env.d.ts
EOF

cat > eslint.config.mjs <<'EOF'
import { defineConfig, globalIgnores } from "eslint/config";
import nextVitals from "eslint-config-next/core-web-vitals";
import nextTs from "eslint-config-next/typescript";
import prettier from "eslint-config-prettier/flat";

const eslintConfig = defineConfig([
  ...nextVitals,
  ...nextTs,
  prettier,
  globalIgnores([
    ".next/**",
    "out/**",
    "build/**",
    "coverage/**",
    "playwright-report/**",
    "test-results/**",
    "next-env.d.ts",
  ]),
]);

export default eslintConfig;
EOF

cat >> .gitignore <<'EOF'

# testing
/playwright-report
/test-results
/blob-report
/playwright/.cache
EOF

echo "24.11.1" > .nvmrc

node -e '
const fs=require("fs");const p=JSON.parse(fs.readFileSync("package.json"));
p.scripts={
  dev:"next dev",
  build:"next build",
  start:"next start",
  lint:"eslint --max-warnings=0",
  "lint:fix":"eslint --fix",
  format:"prettier --write .",
  "format:check":"prettier --check .",
  typecheck:"next typegen && tsc --noEmit",
  test:"vitest",
  "test:run":"vitest run",
  "test:coverage":"vitest run --coverage",
  "test:e2e":"playwright test",
  check:"pnpm typecheck && pnpm lint && pnpm format:check && pnpm test:run",
  prepare:"husky"
};
p.engines={node:">=24"};
p["lint-staged"]={"*.{ts,tsx,js,mjs,cjs}":["eslint --fix --max-warnings=0","prettier --write"],"*.{json,md,css,yml,yaml}":["prettier --write"]};
fs.writeFileSync("package.json",JSON.stringify(p,null,2)+"\n");'

cat > .github/workflows/ci.yml <<'EOF'
name: CI

on:
  push:
    branches: [main]
  pull_request:

jobs:
  check:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: pnpm/action-setup@v4
      - uses: actions/setup-node@v4
        with:
          node-version-file: .nvmrc
          cache: pnpm
      - run: pnpm install --frozen-lockfile
      - run: pnpm check
      - run: pnpm build

  e2e:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: pnpm/action-setup@v4
      - uses: actions/setup-node@v4
        with:
          node-version-file: .nvmrc
          cache: pnpm
      - run: pnpm install --frozen-lockfile
      - run: pnpm exec playwright install --with-deps chromium
      - run: pnpm test:e2e
      - uses: actions/upload-artifact@v4
        if: failure()
        with:
          name: playwright-report
          path: playwright-report
          retention-days: 7
