content.content:
1	"use client";
2	
3	import L from "leaflet";
4	import "leaflet/dist/leaflet.css";
5	import Link from "next/link";
6	import { useEffect, useMemo, useRef, useState } from "react";
7	import { MapContainer, Marker, Popup, TileLayer, useMap } from "react-leaflet";
8	import { amenityLabel } from "@/lib/parks/format";
9	import type { ParkWithCoordinates } from "@/lib/parks/types";
10	
11	/**
12	 * Tiles come from the OpenStreetMap Foundation's public servers by default,
13	 * which is fine for local development and demos but not allowed for
14	 * production traffic. Point these at a tile provider before public launch.
15	 */
16	const TILE_URL =
17	  process.env.NEXT_PUBLIC_MAP_TILE_URL ??
18	  "https://tile.openstreetmap.org/{z}/{x}/{y}.png";
19	const TILE_ATTRIBUTION =
20	  process.env.NEXT_PUBLIC_MAP_TILE_ATTRIBUTION ??
21	  '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors';
22	
23	/** Zoom used when jumping to a single park from the list. */
24	const PARK_ZOOM = 15;
25	
26	export type ShowOnMapRequest = {
27	  parkId: string;
28	  /** Changes on every request so asking for the same park twice still works. */
29	  nonce: number;
30	};
31	
32	type ParkMapProps = {
33	  parks: ParkWithCoordinates[];
34	  selectedId: string | null;
35	  showRequest: ShowOnMapRequest | null;
36	  onSelect: (parkId: string | null) => void;
37	};
38	
39	export default function ParkMap({
40	  parks,
41	  selectedId,
42	  showRequest,
43	  onSelect,
44	}: ParkMapProps) {
45	  const [tilesFailed, setTilesFailed] = useState(false);
46	  const tileStats = useRef({ loaded: 0, failed: 0 });
47	  const reducedMotion = usePrefersReducedMotion();
48	
49	  const bounds = useMemo(
50	    () =>
51	      L.latLngBounds(
52	        parks.map(({ coordinates }) => [coordinates.lat, coordinates.lng]),
53	      ),
54	    // Only fit the initial view; later changes keep the user's pan and zoom.
55	    // eslint-disable-next-line react-hooks/exhaustive-deps
56	    [],
57	  );
58	
59	  return (
60	    <div className="relative h-full w-full">
61	      <MapContainer
62	        bounds={bounds}
63	        boundsOptions={{ padding: [40, 40] }}
64	        maxZoom={18}
65	        zoomAnimation={!reducedMotion}
66	        fadeAnimation={!reducedMotion}
67	        markerZoomAnimation={!reducedMotion}
68	        className="h-full w-full"
69	      >
70	        <TileLayer
71	          url={TILE_URL}
72	          attribution={TILE_ATTRIBUTION}
73	          eventHandlers={{
74	            tileload: () => {
75	              tileStats.current.loaded += 1;
76	              setTilesFailed(false);
77	            },
78	            tileerror: () => {
79	              tileStats.current.failed += 1;
80	              // Only warn when nothing has loaded at all, not for one bad tile.
81	              if (tileStats.current.loaded === 0) setTilesFailed(true);
82	            },
83	          }}
84	        />
85	        <InvalidateSizeOnResize />
86	        <PopupFocusManager />
87	        {parks.map((park) => (
88	          <ParkMarker
89	            key={park.id}
90	            park={park}
91	            selected={park.id === selectedId}
92	            onSelect={onSelect}
93	          />
94	        ))}
95	        {/* After the markers, so their effects (adding them to the map) run
96	            first when the map mounts with a request already pending. */}
97	        <ShowOnMap
98	          request={showRequest}
99	          parks={parks}
100	          reducedMotion={reducedMotion}
101	        />
102	      </MapContainer>
103	      {tilesFailed && (
104	        <p
105	          role="status"
106	          className="border-border bg-surface absolute inset-x-3 top-3 z-[1000] rounded-md border px-3 py-2 text-sm shadow-md"
107	        >
108	          The map background couldn’t load. Park markers still work, and every
109	          park is in the list.
110	        </p>
111	      )}
112	    </div>
113	  );
114	}
115	
116	const PIN_SVG = `<svg viewBox="0 0 30 40" aria-hidden="true" focusable="false"><path fill="currentColor" stroke="#fff" stroke-width="2" d="M15 1.5C7.5 1.5 1.5 7.3 1.5 14.6c0 9.6 11.6 22 12.1 22.6a1.9 1.9 0 0 0 2.8 0c.5-.6 12.1-13 12.1-22.6C28.5 7.3 22.5 1.5 15 1.5Z"/><circle cx="15" cy="14.5" r="5" fill="#fff"/></svg>`;
117	
118	function markerIcon(selected: boolean) {
119	  return L.divIcon({
120	    html: PIN_SVG,
121	    className: selected ? "park-marker park-marker--selected" : "park-marker",
122	    // A 44x44 target (WCAG 2.5.5) whose bottom center is the pin's tip.
123	    iconSize: [44, 44],
124	    iconAnchor: [22, 42],
125	    popupAnchor: [0, -40],
126	  });
127	}
128	
129	function ParkMarker({
130	  park,
131	  selected,
132	  onSelect,
133	}: {
134	  park: ParkWithCoordinates;
135	  selected: boolean;
136	  onSelect: (parkId: string | null) => void;
137	}) {
138	  const icon = useMemo(() => markerIcon(selected), [selected]);
139	  const markerRef = useRef<L.Marker>(null);
140	  const label = park.address ? `${park.name}, ${park.address}` : park.name;
141	
142	  // Marker (a child) adds itself to the map in its own effect, which runs
143	  // before this one, so the icon element exists here.
144	  useEffect(() => {
145	    if (markerRef.current) {
146	      enhanceMarkerElement(markerRef.current, park.id, label);
147	    }
148	  }, [park.id, label]);
149	
150	  return (
151	    <Marker
152	      ref={markerRef}
153	      position={[park.coordinates.lat, park.coordinates.lng]}
154	      icon={icon}
155	      title={park.name}
156	      eventHandlers={{
157	        popupopen: () => onSelect(park.id),
158	        popupclose: () => onSelect(null),
159	      }}
160	    >
161	      <Popup>
162	        <ParkPopup park={park} />
163	      </Popup>
164	    </Marker>
165	  );
166	}
167	
168	/**
169	 * Leaflet makes markers focusable with role="button", but only gives them a
170	 * `title` and only opens the popup on Enter. Give each marker a proper
171	 * accessible name and support Space too, as a native button would.
172	 *
173	 * Leaflet reuses the same element when a divIcon changes (e.g. on
174	 * selection), so this only needs to run once per element.
175	 */
176	function enhanceMarkerElement(marker: L.Marker, parkId: string, label: string) {
177	  const element = marker.getElement();
178	  if (!element || element.dataset.parkId === parkId) return;
179	  element.dataset.parkId = parkId;
180	  element.setAttribute("aria-label", `${label}. Show park summary.`);
181	  element.addEventListener("keydown", (event) => {
182	    if (event.key === " ") {
183	      event.preventDefault();
184	      marker.openPopup();
185	    }
186	  });
187	}
188	
189	function ParkPopup({ park }: { park: ParkWithCoordinates }) {
190	  const amenities = park.amenities.slice(0, 3).map(amenityLabel);
191	  const more = park.amenities.length - amenities.length;
192	
193	  return (
194	    <div className="flex min-w-48 flex-col gap-1.5">
195	      <p className="text-base font-semibold">{park.name}</p>
196	      <p className="text-muted">{park.address ?? "Address not listed"}</p>
197	      {amenities.length > 0 && (
198	        <p className="text-muted">
199	          {amenities.join(" · ")}
200	          {more > 0 && ` · +${more} more`}
201	        </p>
202	      )}
203	      <Link
204	        href={`/parks/${park.id}`}
205	        className="text-accent hover:text-accent-hover mt-1 font-semibold underline underline-offset-2"
206	        data-popup-primary={park.id}
207	      >
208	        View park details
209	        <span className="sr-only">: {park.name}</span>
210	      </Link>
211	    </div>
212	  );
213	}
214	
215	/** Pans to a park and opens its popup when the list asks for it. */
216	function ShowOnMap({
217	  request,
218	  parks,
219	  reducedMotion,
220	}: {
221	  request: ShowOnMapRequest | null;
222	  parks: ParkWithCoordinates[];
223	  reducedMotion: boolean;
224	}) {
225	  const map = useMap();
226	
227	  useEffect(() => {
228	    if (!request) return;
229	    const park = parks.find((candidate) => candidate.id === request.parkId);
230	    if (!park) return;
231	
232	    // The map may have just been revealed (mobile List/Map toggle) and still
233	    // think it is 0x0, which would break centering.
234	    map.invalidateSize();
235	    const target = L.latLng(park.coordinates.lat, park.coordinates.lng);
236	    map.setView(target, Math.max(map.getZoom(), PARK_ZOOM), {
237	      animate: !reducedMotion,
238	    });
239	
240	    map.eachLayer((layer) => {
241	      if (
242	        layer instanceof L.Marker &&
243	        layer.getElement()?.dataset.parkId === park.id
244	      ) {
245	        layer.openPopup();
246	      }
247	    });
248	    // Only react to new requests, not to the parks list being re-created.
249	    // eslint-disable-next-line react-hooks/exhaustive-deps
250	  }, [request, map]);
251	
252	  return null;
253	}
254	
255	/**
256	 * Leaflet popups don't manage focus. Move focus into a popup when it opens so
257	 * keyboard and screen reader users land on its content, and put focus back
258	 * on whatever opened it (a marker or a "Show on map" button) when it closes.
259	 */
260	function PopupFocusManager() {
261	  const map = useMap();
262	
263	  useEffect(() => {
264	    let opener: HTMLElement | null = null;
265	
266	    const onOpen = (event: L.PopupEvent) => {
267	      const active = document.activeElement;
268	      opener = active instanceof HTMLElement ? active : null;
269	      const container = event.popup.getElement();
270	      container
271	        ?.querySelector<HTMLElement>("[data-popup-primary]")
272	        ?.focus({ preventScroll: true });
273	    };
274	
275	    const onClose = (event: L.PopupEvent) => {
276	      const container = event.popup.getElement();
277	      const active = document.activeElement;
278	      const focusWasInPopup =
279	        active === null ||
