import {
  expect,
  isMobile,
  marker,
  openMapView,
  parkCard,
  test,
  TILE_URL_PATTERN,
} from "./fixtures";

test.describe("home page", () => {
  test.beforeEach(async ({ page }) => {
    await page.goto("/");
  });

  test("lists every park alphabetically", async ({ page }) => {
    await expect(page).toHaveTitle("Find a Park · New York City");
    await expect(
      page.getByRole("heading", { level: 1, name: "Find a park" }),
    ).toBeVisible();

    const names = await page
      .getByRole("list", { name: "Parks" })
      .getByRole("heading", { level: 2 })
      .allTextContents();
    expect(names).toHaveLength(12);
    expect(names).toEqual([...names].sort((a, b) => a.localeCompare(b)));
    await expect(page.getByRole("status").first()).toHaveText(
      "Showing all 12 parks",
    );
  });

  test("shows missing information honestly on cards", async ({ page }) => {
    await expect(parkCard(page, "Highland Dog Park")).toContainText(
      "Address not listed",
    );
    // Cedar Hill has no rating, so its card shows none rather than a guess.
    await expect(parkCard(page, "Cedar Hill Nature Preserve")).not.toContainText(
      "out of 5",
    );
  });

  test("a keyboard user can open a park's details from the list", async ({
    page,
  }) => {
    const target = page.getByRole("link", { name: "Prospect Park" });

    // Tab from the top of the page, as a keyboard user would.
    let reached = false;
    for (let presses = 0; presses < 80 && !reached; presses++) {
      await page.keyboard.press("Tab");
      reached = await target.evaluate((link) => link === document.activeElement);
    }
    expect(reached, "Prospect Park link should be reachable with Tab").toBe(
      true,
    );

    // The focus indicator is visible.
    const outline = await target.evaluate((link) => {
      const style = getComputedStyle(link);
      return { style: style.outlineStyle, width: style.outlineWidth };
    });
    expect(outline.style).not.toBe("none");
    expect(parseFloat(outline.width)).toBeGreaterThanOrEqual(2);

    await page.keyboard.press("Enter");
    await expect(page).toHaveURL(/\/parks\/prospect-park$/);
    await expect(
      page.getByRole("heading", { level: 1, name: "Prospect Park" }),
    ).toBeVisible();
  });

  test("the skip link jumps to the main content", async ({ page }) => {
    await page.keyboard.press("Tab");
    const skip = page.getByRole("link", { name: "Skip to main content" });
    await expect(skip).toBeFocused();
    await expect(skip).toBeInViewport();
    await page.keyboard.press("Enter");
    await expect(page.locator("#main")).toBeFocused();
  });

  test("“Show on map” opens the park's popup and returns focus on Escape", async ({
    page,
  }, testInfo) => {
    const button = page.getByRole("button", {
      name: "Show on map: Prospect Park",
    });
    await button.click();

    const details = page.getByRole("link", {
      name: "View park details: Prospect Park",
    });
    await expect(details).toBeVisible();
    await expect(details).toBeFocused();
    await expect(parkCard(page, "Prospect Park")).toHaveAttribute(
      "class",
      /border-accent/,
    );

    await page.keyboard.press("Escape");
    await expect(details).toBeHidden();
    if (isMobile(testInfo.project.name)) {
      // The list is hidden behind the map on phones, so focus goes to the marker.
      await expect(marker(page, "Prospect Park")).toBeFocused();
    } else {
      await expect(button).toBeFocused();
    }
  });

  test("map markers work with the keyboard", async ({ page }, testInfo) => {
    await openMapView(page, testInfo.project.name);
    await expect(page.locator(".park-marker")).toHaveCount(12);

    const pin = marker(page, "Central Plaza Green");
    await pin.focus();
    await page.keyboard.press("Enter");
    const details = page.getByRole("link", {
      name: "View park details: Central Plaza Green",
    });
    await expect(details).toBeFocused();

    await page.keyboard.press("Escape");
    await expect(details).toBeHidden();
    await expect(pin).toBeFocused();

    // Space works too, as on a native button, including on a second open.
    await page.keyboard.press(" ");
    await expect(details).toBeFocused();

    await page.keyboard.press("Enter");
    await expect(page).toHaveURL(/\/parks\/central-plaza-green$/);
  });

  test("search filters the list and the map together", async ({
    page,
  }, testInfo) => {
    await page.getByLabel("Search parks").fill("dog run");
    await expect(page.getByRole("status").first()).toHaveText(
      "Showing 2 of 12 parks",
    );
    await expect(
      page.getByRole("list", { name: "Parks" }).getByRole("article"),
    ).toHaveCount(2);

    await openMapView(page, testInfo.project.name);
    await expect(page.locator(".park-marker")).toHaveCount(2);
  });

  test("a search with no matches explains itself and can be cleared", async ({
    page,
  }) => {
    await page.getByLabel("Search parks").fill("volcano");
    await expect(page.getByText(/No parks match/)).toBeVisible();
    await page.getByRole("button", { name: "Clear search" }).click();
    await expect(page.getByLabel("Search parks")).toHaveValue("");
    await expect(
      page.getByRole("list", { name: "Parks" }).getByRole("article"),
    ).toHaveCount(12);
  });

  test("the map still works after visiting a park and going back", async ({
    page,
  }, testInfo) => {
    // Regression test: Next.js keeps the home page mounted but hidden while
    // you're on another page; react-leaflet's MapContainer crashed on return.
    await openMapView(page, testInfo.project.name);
    await expect(page.locator(".park-marker")).toHaveCount(12);

    await page.getByRole("link", { name: "Prospect Park" }).first().click({
      // On phones the list link is hidden behind the map view.
      force: isMobile(testInfo.project.name),
    });
    await expect(page).toHaveURL(/\/parks\/prospect-park$/);

    await page.goBack();
    await expect(page.getByRole("heading", { name: "Find a park" })).toBeVisible();
    await openMapView(page, testInfo.project.name);
    await expect(page.locator(".park-marker")).toHaveCount(12);
    await expect(page.getByText("The map couldn’t be loaded")).toHaveCount(0);
  });
});

test.describe("phone layout", () => {
  test.skip(({}, testInfo) => !isMobile(testInfo.project.name), "phones only");

  test("shows the list first and the map on request", async ({ page }) => {
    await page.goto("/");
    const list = page.getByRole("list", { name: "Parks" });
    const map = page.locator(".park-map");

    await expect(list).toBeVisible();
    await expect(map).toHaveCount(0); // not even loaded until it's needed

    await page.getByRole("button", { name: "Map", exact: true }).click();
    await expect(page.getByRole("button", { name: "Map", exact: true })).toHaveAttribute(
      "aria-pressed",
      "true",
    );
    await expect(map).toBeVisible();
    await expect(list).toBeHidden();
  });
});

test.describe("when the map can't load", () => {
  test("map tiles failing shows a notice and the list keeps working", async ({
    page,
  }, testInfo) => {
    await page.unroute(TILE_URL_PATTERN);
    await page.route(TILE_URL_PATTERN, (route) => route.abort());
    await page.goto("/");
    await openMapView(page, testInfo.project.name);

    await expect(
      page.getByText("The map background couldn’t load."),
    ).toBeVisible();
    // Markers still render on the blank map.
    await expect(page.locator(".park-marker")).toHaveCount(12);
  });

  test("the map code failing to load leaves the list usable", async ({
    page,
  }, testInfo) => {
    // Fail the map's JavaScript chunk.
    await page.route(/park-map.*\.js$/, (route) => route.abort());
    await page.goto("/");
    await openMapView(page, testInfo.project.name);

    await expect(page.getByText("The map couldn’t be loaded.")).toBeVisible();
    if (!isMobile(testInfo.project.name)) {
      await page.getByRole("link", { name: "Prospect Park" }).click();
      await expect(page).toHaveURL(/\/parks\/prospect-park$/);
    }
  });
});

import { expect, test } from "./fixtures";

test.describe("park details page", () => {
  test("shows everything known about a park", async ({ page }) => {
    await page.goto("/parks/prospect-park");

    await expect(page).toHaveTitle("Prospect Park · Find a Park");
    await expect(
      page.getByRole("heading", { level: 1, name: "Prospect Park" }),
    ).toBeVisible();
    await expect(page.getByText(/526-acre park in the heart of Brooklyn/)).toBeVisible();

    const visit = page.getByRole("complementary", { name: "Plan your visit" });
    await expect(visit).toContainText("6:00 AM - 1:00 AM");
    await expect(visit).toContainText("Brooklyn, NY 11225");
    await expect(visit).toContainText("526 acres");
    await expect(visit).toContainText("4.7 out of 5");

    for (const amenity of ["Playground", "Dog run", "Picnic areas"]) {
      await expect(page.getByRole("listitem").filter({ hasText: amenity })).toBeVisible();
    }

    const directions = page.getByRole("link", { name: /Get directions/ });
    await expect(directions).toHaveAttribute(
      "href",
      "https://www.google.com/maps/dir/?api=1&destination=40.6602%2C-73.969",
    );
    await expect(directions).toHaveAttribute("target", "_blank");
  });

  test("says when information isn't listed instead of inventing it", async ({
    page,
  }) => {
    // No description in the data.
    await page.goto("/parks/old-mill-botanical-garden");
    await expect(page.getByText("No description available.")).toBeVisible();

    // No address in the data.
    await page.goto("/parks/highland-dog-park");
    const visit = page.getByRole("complementary", { name: "Plan your visit" });
    await expect(visit.getByText("Not listed")).toHaveCount(1);
    await expect(visit).toContainText("Address");

    // No rating and no photos in the data.
    await page.goto("/parks/cedar-hill-nature-preserve");
    await expect(page.getByText("No photos available.")).toBeVisible();
    await expect(
      page.getByRole("complementary", { name: "Plan your visit" }),
    ).not.toContainText("out of 5");
  });

  test("replaces photos that fail to load with a labeled placeholder", async ({
    page,
  }) => {
    await page.goto("/parks/old-mill-botanical-garden");
    const placeholders = page.getByRole("img", { name: /unavailable/ });
    await expect(placeholders).toHaveCount(2);
    await expect(placeholders.first()).toHaveAccessibleName(
      "Old Mill Botanical Garden, photo 1 of 2 (unavailable)",
    );
  });

  test("“All parks” returns to the list", async ({ page }) => {
    await page.goto("/parks/lakeshore-point");
    await page.getByRole("link", { name: "All parks" }).click();
    await expect(page).toHaveURL(/\/$/);
    await expect(page.getByRole("heading", { name: "Find a park" })).toBeVisible();
  });

  test("an unknown park returns a real 404 page", async ({ page }) => {
    const response = await page.goto("/parks/no-such-park");
    expect(response?.status()).toBe(404);
    await expect(
      page.getByRole("heading", { name: "We couldn’t find that page" }),
    ).toBeVisible();
    await page.getByRole("link", { name: "Browse all parks" }).click();
    await expect(page).toHaveURL(/\/$/);
  });
});

import AxeBuilder from "@axe-core/playwright";
import type { Page } from "@playwright/test";
import { expect, openMapView, test } from "./fixtures";

/**
 * Automated WCAG 2.2 AA checks. These catch a useful subset of problems
 * (contrast, names, roles, landmarks); the keyboard tests in the other
 * specs and manual screen reader testing cover what axe can't.
 */
async function expectNoViolations(page: Page) {
  const results = await new AxeBuilder({ page })
    .withTags(["wcag2a", "wcag2aa", "wcag21a", "wcag21aa", "wcag22aa"])
    .analyze();
  const summary = results.violations.map(
    (violation) =>
      `${violation.id} (${violation.impact}): ${violation.help}\n  ${violation.nodes
        .slice(0, 3)
        .map((node) => node.target.join(" "))
        .join("\n  ")}`,
  );
  expect(summary).toEqual([]);
}

