function ParkPopup({ park }: { park: ParkWithCoordinates }) {
  const linkRef = useRef<HTMLAnchorElement>(null);
  const amenities = park.amenities.slice(0, 3).map(amenityLabel);
  const more = park.amenities.length - amenities.length;

