        ?.querySelector<HTMLElement>("[data-popup-primary]")
        ?.getAttribute("data-popup-primary");
      if (parkId) {
        map
          .getContainer()
          .querySelector<HTMLElement>(
            `.park-marker[data-park-id="${CSS.escape(parkId)}"]`,
          )
          ?.focus({ preventScroll: true });
      }
    };

