  ::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* ---- Leaflet overrides ----------------------------------------------------
 * leaflet.css loads after this file (with the map's code), so every override
 * is scoped under .park-map to win on specificity rather than source order.
 */

.park-map .leaflet-container {
  font: inherit;
  background: var(--surface-muted);
  /* Keep map controls and popups below the sticky header and skip link. */
  z-index: 0;
}

.park-marker {
  /* Reset Leaflet's default divIcon box. */
  background: none;
  border: none;
  color: var(--marker);
  /* A real button target: the pin graphic sits inside a 44x44 hit area. */
  display: grid;
  place-items: end center;
  border-radius: 9999px;
  cursor: pointer;
}

.park-marker svg {
  width: 30px;
  height: 40px;
  filter: drop-shadow(0 1px 1.5px rgb(0 0 0 / 0.45));
  transition: transform 120ms ease-out;
}

