  transform: scale(1.12);
}

.park-marker--selected {
  color: var(--marker-selected);
  z-index: 1000 !important;
}

.park-marker--selected svg {
  transform: scale(1.2);
}

.park-map .park-marker:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 0;
}

