import { test } from "./fixtures";
test("trace show on map pan", async ({ page }) => {
  await page.goto("/");
  await page.getByRole("button", { name: "Show on map: Prospect Park" }).click();
  await page.waitForTimeout(1000);
  await page.evaluate(() => {
    (window as any).__events = [];
    const c = document.querySelector(".leaflet-container")!;
    const pane = document.querySelector(".leaflet-map-pane") as HTMLElement;
    new MutationObserver(() => (window as any).__events.push(["pane", Math.round(performance.now()), pane.style.transform])).observe(pane, { attributes: true, attributeFilter: ["style"] });
    for (const t of ["focusin"]) document.addEventListener(t, (e) => (window as any).__events.push([t, Math.round(performance.now()), (e.target as HTMLElement).getAttribute("aria-label") ?? (e.target as HTMLElement).tagName]));
  });
  await page.getByRole("button", { name: "Show on map: Willow Creek Wetlands" }).click();
  await page.waitForTimeout(1200);
  const map = (await page.locator(".leaflet-container").boundingBox())!;
  const pin = (await page.locator('.park-marker[data-park-id="willow-creek-wetlands"]').boundingBox())!;
  console.log("OFFSET", Math.round(pin.x + 22 - (map.x + map.width / 2)), Math.round(pin.y + 42 - (map.y + map.height / 2)));
  const ev = await page.evaluate(() => (window as any).__events);
  for (const e of ev.slice(0, 12)) console.log("EV", JSON.stringify(e));
  console.log("EV count", ev.length, "last", JSON.stringify(ev.at(-1)));
});
