19	      ),
20	    }))
21	    .filter((violation) => violation.nodes.length > 0);
22	  const summary = violations.map(
23	    (violation) =>
24	      `${violation.id} (${violation.impact}): ${violation.help}\n  ${violation.nodes
25	        .slice(0, 3)
