5	
6	/** How many amenities a card shows before summarizing the rest. */
7	const CARD_AMENITY_LIMIT = 4;
8	
9	type ParkListProps = {
10	  parks: Park[];
11	  selectedId: string | null;
12	  onShowOnMap: (parkId: string) => void;
13	};
14	
15	export function ParkList({ parks, selectedId, onShowOnMap }: ParkListProps) {
16	  return (
17	    // role="list" because Safari drops list semantics from unstyled lists.
18	    <ul role="list" className="flex flex-col gap-3" aria-label="Parks">
19	      {parks.map((park) => (
20	        <li key={park.id}>
21	          <ParkCard
22	            park={park}
23	            selected={park.id === selectedId}
24	            onShowOnMap={onShowOnMap}
25	          />
26	        </li>
27	      ))}
28	    </ul>
29	  );
30	}
31	
32	function ParkCard({
33	  park,
34	  selected,
35	  onShowOnMap,
36	}: {
37	  park: Park;
38	  selected: boolean;
39	  onShowOnMap: (parkId: string) => void;
40	}) {
41	  const headingId = `park-card-${park.id}`;
42	  const shownAmenities = park.amenities.slice(0, CARD_AMENITY_LIMIT);
43	  const hiddenAmenityCount = park.amenities.length - shownAmenities.length;
44	
45	  return (
46	    <article
47	      aria-labelledby={headingId}
48	      data-park-card={park.id}
49	      className={cn(
50	        "flex flex-col gap-2 rounded-lg border bg-surface p-4 transition-colors",
51	        selected
52	          ? "border-accent bg-accent-soft ring-1 ring-accent"
53	          : "border-border",
54	      )}
55	    >
56	      <h2 id={headingId} className="text-lg leading-snug font-semibold">
57	        <Link
58	          href={`/parks/${park.id}`}
59	          className="rounded-sm text-accent underline-offset-2 hover:text-accent-hover hover:underline"
60	        >
61	          {park.name}
62	        </Link>
63	      </h2>
64	
65	      <p className={cn("text-sm", park.address ? "" : "text-muted italic")}>
66	        {park.address ?? "Address not listed"}
67	      </p>
68	
69	      {(park.rating !== null || park.hours || park.acreage !== null) && (
70	        <dl className="flex flex-wrap gap-x-4 gap-y-1 text-sm text-muted">
71	          {park.rating !== null && (
72	            <div className="flex items-center gap-1">
73	              <dt className="sr-only">Rating</dt>
74	              <dd className="flex items-center gap-1">
75	                <StarIcon />
76	                <span aria-hidden="true">{park.rating.toFixed(1)}</span>
77	                <span className="sr-only">{formatRating(park.rating)}</span>
78	              </dd>
79	            </div>
